#define LIBRARY
#include "count.cpp"
#include <random>
#include <filesystem>
namespace fs=std::filesystem;
void save(const vector<C>&cs,string path){ofstream f(path);for(C c:cs)f<<c.a+1<<' '<<c.b+1<<' '<<c.c+1<<' '<<c.i+1<<'N'<<c.j+1<<'\n';}
vector<C> restrict_to(const vector<C>&cs,vector<int> keep){vector<C>out;map<int,int>m;for(int x:keep)m[x]=m.size();for(C c:cs)if(m.count(c.a)&&m.count(c.b)&&m.count(c.c))out.push_back({m[c.a],m[c.b],m[c.c],c.i,c.j});return out;}
vector<C> relabel(const vector<C>&cs,vector<int>p,bool reverse){vector<C>out;for(C c:cs){int old[3]={c.a,c.b,c.c};int target=p[old[c.i]];int t[3]={p[c.a],p[c.b],p[c.c]};sort(t,t+3);int i=find(t,t+3,target)-t;out.push_back({t[0],t[1],t[2],i,reverse?2-c.j:c.j});}return out;}
vector<C> clone(const vector<C>&cs,int n,int v,int mode){vector<C>out=cs;map<tuple<int,int,int>,C>lookup;for(auto c:cs)lookup[{c.a,c.b,c.c}]=c;for(int a=0;a<n;a++)for(int b=a+1;b<n;b++){if(a==v||b==v){int t[3]={a,b,n};int i=mode/3,j=mode%3; // mode literal triple rank
out.push_back({a,b,n,i,j});}else{int orig[3]={a,b,v};sort(orig,orig+3);C c=lookup.at({orig[0],orig[1],orig[2]});int x=orig[c.i];if(x==v)x=n;int t[3]={a,b,n};out.push_back({a,b,n,int(find(t,t+3,x)-t),c.j});}}return out;}
int main(int argc,char**argv){try{string mode=argv[1],input=argv[2],dir=argv[3];fs::create_directories(dir);auto src=readfile(input,25);if(mode=="symmetry"){vector<int> p(25);iota(p.begin(),p.end(),0);for(int k=0;k<4;k++){if(k==1)reverse(p.begin(),p.end());if(k==2)rotate(p.begin(),p.begin()+7,p.end());if(k==3){mt19937 g(17);shuffle(p.begin(),p.end(),g);}for(int rev=0;rev<2;rev++){auto cs=relabel(src,p,rev);auto r=count(25,cs);cout<<k<<','<<rev<<','<<dec(r.value)<<','<<r.states<<endl;}}}else if(mode=="restrict"){for(int n=9;n<=24;n++){U best=0;int beststart=-1;for(int start=0;start<=25-n;start++){vector<int>keep(n);iota(keep.begin(),keep.end(),start);auto cs=restrict_to(src,keep);auto r=count(n,cs);cout<<"interval,"<<n<<','<<start<<','<<dec(r.value)<<endl;if(r.value>best){best=r.value;beststart=start;save(cs,dir+"/best-"+to_string(n)+".txt");}}cout<<"best,"<<n<<','<<beststart<<','<<dec(best)<<endl;}for(int drop=0;drop<25;drop++){vector<int>keep;for(int i=0;i<25;i++)if(i!=drop)keep.push_back(i);auto cs=restrict_to(src,keep);auto r=count(24,cs);cout<<"delete,"<<drop<<','<<dec(r.value)<<endl;save(cs,dir+"/delete-"+to_string(drop)+".txt");}}else if(mode=="clone"){for(int n=8;n<=24;n++){vector<int>keep(n);iota(keep.begin(),keep.end(),0);auto base=restrict_to(src,keep);U best=0;int bv=-1,bm=-1;for(int v=0;v<n;v++)for(int m=0;m<9;m++){auto cs=clone(base,n,v,m);auto r=count(n+1,cs);if(r.value>best){best=r.value;bv=v;bm=m;save(cs,dir+"/best-"+to_string(n+1)+".txt");}cout<<"clone,"<<n+1<<','<<v<<','<<m<<','<<dec(r.value)<<endl;}cout<<"best,"<<n+1<<','<<bv<<','<<bm<<','<<dec(best)<<endl;}}else throw runtime_error("mode");}catch(exception&e){cerr<<e.what()<<endl;return 2;}}
